{"command":"cat <<'PY' > /tmp/probe.py
import subprocess, time, sys
def run(cmd): return subprocess.run(cmd, shell=True, capture_output=True, text=True)
class Sess:
    def __init__(self, name, args="", w=80, h=24):
        self.name=name
        run(f"tmux kill-session -t {name} 2>/dev/null")
        cmd=f"cd /workspace && ./executable {args}; echo EXIT:$?; sleep 100"
        # escape quotes
        cmd_esc=cmd.replace('"','\\"')
        run(f'tmux new-session -d -s {name} -x {w} -y {h} "{cmd_esc}"')
        time.sleep(0.9)
    def cap(self, esc=False):
        flag="-e" if esc else ""
        out=run(f"tmux capture-pane -t {self.name} -p {flag}")
        return out.stdout
    def print(self, esc=False):
        s=self.cap(esc)
        for i,line in enumerate(s.splitlines()):
            print(f"{i:02d}|{line}|")
    def keys(self, *ks, delay=0.3):
        for k in ks:
            # k could be special name or literal string
            # Use send-keys -l for literal? We'll handle: if len>1 and in special list, without -l else...
            specials={"Escape","Enter","Space","BSpace","Tab","C-c","C-d","Up","Down","Left","Right"}
            if k in specials:
                run(f"tmux send-keys -t {self.name} {k}")
            else:
                # send literally char by char using -l
                for ch in k:
                    if ch==" ":
                        run(f"tmux send-keys -t {self.name} Space")
                    else:
                        # quote
                        import shlex
                        run(f"tmux send-keys -t {self.name} -l {shlex.quote(ch)}")
            time.sleep(delay)
    def kill(self):
        run(f"tmux kill-session -t {self.name} 2>/dev/null")
