def trial(seq_desc, seq_keys):
    s=Sess("test","--nokb -c 1 -r 1",80,24)
    les=s.cap().splitlines()[6][1:-1].strip()
    print(f"\n=== trial {seq_desc} lesson={les!r} ===")
