import sys; sys.path.insert(0,'/tmp')
from probe import Sess, run
import time, shlex

def get_lesson(s):
    return s.cap().splitlines()[6][1:-1].strip()

def send(s, txt):
    if txt=="SPACE": s.keys("Space", delay=0.4)
    elif txt=="BSpace": s.keys("BSpace", delay=0.4)
    else:
        run(f"tmux send-keys -t test -l {shlex.quote(txt)}"); time.sleep(0.4)

def trial(desc, maker):
    s=Sess("test","--nokb -c 1 -r 1",80,24)
    les=get_lesson(s)
    seq=maker(les)
    print(f"\n=== {desc} lesson={les!r} seq={seq!r} ===")
    for k in seq:
        send(s,k)
        print(f" after {k!r}: row6={s.cap().splitlines()[6].strip()!r} row7={s.cap().splitlines()[7].strip()!r} row3={s.cap().splitlines()[3].strip()!r} esc6={s.cap(True).splitlines()[6]!r} esc7={s.cap(True).splitlines()[7]!r}")
    s.kill()

trial("correct incl trailing space", lambda les: [les+" "])
trial("correct no trailing space", lambda les: [les])
trial("all x incl space pos", lambda les: ["x"* (len(les)+1)])
trial("correct letters, x for spaces, final space correct", lambda les: [les.replace(" ","x")+" "])
trial("wrong last char then bspace correct", lambda les: [les+"x", "BSpace", "SPACE"])
PY
python3 /tmp/t7.py 2>&1 | head -n 300
