import sys; sys.path.insert(0,'/tmp')
from probe import Sess
import re
ansi=re.compile(r'\x1b\[([0-9;?]*)([A-Za-z])')
def parse_line(line):
    out=[]; pos=0; idx=0; style="default"; buf=""; start=0
    while pos < len(line):
        m=ansi.match(line,pos)
        if m:
            if buf: out.append((start,buf,style)); buf=""
            style=m.group(0); pos=m.end(); start=idx; continue
        buf+=line[pos]; idx+=1; pos+=1
    if buf: out.append((start,buf,style))
    return out
for args in ["","--cat --nokb"]:
    s=Sess("test",args,80,24)
    print("ARGS",args)
    for r,line in enumerate(s.cap(True).splitlines()[:19]):
        print("row",r)
        for st,txt,sty in parse_line(line): print(f"  @{st} len={len(txt)} sty={sty!r} txt={txt!r}")
    s.kill()
