#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Layout {
    pub rows: [&'static str; 3],
}

pub const QWERTY: Layout = Layout {
    rows: ["qwertyuiop[]", "asdfghjkl;'", "zxcvbnm,./"],
};
pub const QWERTZ: Layout = Layout {
    rows: ["qwertzuiopü+", "asdfghjklöä", "yxcvbnm,.-"],
};
pub const AZERTY: Layout = Layout {
    rows: ["azertyuiop^$", "qsdfghjklmù", "wxcvbn,;:!"],
};
pub const DVORAK: Layout = Layout {
    rows: ["',.pyfgcrl/=", "aoeuidhtns-", ";qjkxbmwvz"],
};
pub const COLEMAK: Layout = Layout {
    rows: ["qwfpgjluy;[]", "arstdhneio'", "zxcvbkm,./"],
};
pub const COLEMAKDH: Layout = Layout {
    rows: ["qwfpbjluy;[]", "arstgmneio'", "zxcdvkh,./"],
};

pub fn layout_for(name: &str) -> Layout {
    match name {
        "qwerty" => QWERTY,
        "qwertz" => QWERTZ,
        "azerty" => AZERTY,
        "dvorak" => DVORAK,
        "colemak" => COLEMAK,
        "colemakdh" => COLEMAKDH,
        _ => QWERTY,
    }
}

pub fn translate(c: char, from: Layout, to: Layout) -> char {
    let from_chars: Vec<char> = from.rows.iter().flat_map(|row| row.chars()).collect();
    if let Some(pos) = from_chars.iter().position(|candidate| *candidate == c) {
        let to_chars: Vec<char> = to.rows.iter().flat_map(|row| row.chars()).collect();
        if let Some(mapped) = to_chars.get(pos) {
            return *mapped;
        }
    }
    c
}

fn keys_row(row: &str) -> Vec<char> {
    row.chars().collect()
}

pub fn keyboard_lines(layout: Layout, ortho: bool) -> Vec<String> {
    let first = keys_row(layout.rows[0]);
    let second = keys_row(layout.rows[1]);
    let third = keys_row(layout.rows[2]);

    let key_line = |keys: &[char]| -> String {
        let mut line = String::new();
        for key in keys {
            line.push('│');
            line.push(' ');
            line.push(*key);
            line.push(' ');
        }
        line.push('│');
        line
    };

    if ortho {
        let mut second_ortho = second.clone();
        second_ortho.push('△');
        let mut third_ortho = third.clone();
        third_ortho.push('△');
        third_ortho.push('△');
        let separator = "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤".to_string();
        vec![
            "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐".to_string(),
            key_line(&first),
            separator.clone(),
            key_line(&second_ortho),
            separator,
            key_line(&third_ortho),
            "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘".to_string(),
        ]
    } else {
        vec![
            "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐".to_string(),
            key_line(&first),
            "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string(),
            format!(" {}", key_line(&second)),
            " └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘".to_string(),
            format!("  {}", key_line(&third)),
            "  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘".to_string(),
        ]
    }
}
