cat > /workspace/src/game.rs <<'RS'
use crate::layouts::{layout_for, translate, Layout};
use rand::seq::SliceRandom;
use std::time::Instant;

pub struct Game {
    pub pool: Vec<String>,
    pub top: i32,
    pub combi: i32,
    pub rep: i32,
    pub wpm_needed: i32,
    pub acc_needed: i32,
    pub emu_in: Layout,
    pub emu_out: Layout,
    pub show_ortho: bool,
    pub show_keyboard: bool,
    pub cat: bool,

    pub lesson_number: usize,
    pub target: Vec<char>,
    pub input: Vec<char>,
    pub successes: usize,
    pub failures: usize,
    pub last_wpm: usize,
    pub last_acc: usize,
    pub avg_wpm: usize,
    pub avg_acc: usize,

    correct_strokes: usize,
    total_strokes: usize,
    wpm_values: Vec<usize>,
    acc_values: Vec<usize>,
    started: Option<Instant>,
}

impl Game {
    pub fn new(
        pool: Vec<String>,
        top: i32,
        combi: i32,
        rep: i32,
        wpm_needed: i32,
        acc_needed: i32,
        emu_in_name: &str,
        emu_out_name: &str,
        show_ortho: bool,
        show_keyboard: bool,
        cat: bool,
    ) -> Self {
        Self {
            pool,
            top,
            combi,
            rep,
            wpm_needed,
            acc_needed,
            emu_in: layout_for(emu_in_name),
            emu_out: layout_for(emu_out_name),
            show_ortho,
            show_keyboard,
            cat,
            lesson_number: 0,
            target: Vec::new(),
            input: Vec::new(),
            successes: 0,
            failures: 0,
            last_wpm: 0,
            last_acc: 0,
            avg_wpm: 0,
            avg_acc: 0,
            correct_strokes: 0,
            total_strokes: 0,
            wpm_values: Vec::new(),
            acc_values: Vec::new(),
            started: None,
        }
    }

    pub fn new_lesson(&mut self) {
        self.lesson_number += 1;
        let usable = self.top.max(0) as usize;
        let choices: Vec<String> = self.pool.iter().take(usable).cloned().collect();
        let mut rng = rand::thread_rng();
        let mut selected: Vec<String> = Vec::new();
        for _ in 0..self.combi {
            let item = choices.choose(&mut rng).unwrap().clone();
            selected.push(item);
        }
        let mut target = String::new();
        for _ in 0..self.rep {
            for item in &selected {
                target.push_str(item);
                target.push(' ');
            }
        }
        self.target = target.chars().collect();
        self.input.clear();
        self.correct_strokes = 0;
        self.total_strokes = 0;
        self.started = None;
    }

    fn finish_lesson_if_complete(&mut self) {
        if self.input != self.target {
            return;
        }
        let elapsed = self.started.map(|start| start.elapsed()).unwrap_or_default();
        let non_space = self.target.iter().filter(|c| **c != ' ').count() as f64;
        let words = non_space / 5.0;
        let minutes = elapsed.as_secs_f64() / 60.0;
        let wpm = if minutes > 0.0 {
            (words / minutes) as usize
        } else {
            0
        };
        let acc = if self.total_strokes > 0 {
            (self.correct_strokes as f64 / self.total_strokes as f64 * 100.0) as usize
        } else {
            0
        };
        self.last_wpm = wpm;
        self.last_acc = acc;
        self.wpm_values.push(wpm);
        self.acc_values.push(acc);
        self.avg_wpm = self.wpm_values.iter().sum::<usize>() / self.wpm_values.len();
        self.avg_acc = self.acc_values.iter().sum::<usize>() / self.acc_values.len();
        if wpm >= self.wpm_needed as usize && acc >= self.acc_needed as usize {
            self.successes += 1;
        } else {
            self.failures += 1;
        }
        self.new_lesson();
    }

    fn note_removed(&mut self, index: usize, removed: char) {
        if let Some(expected) = self.target.get(index) {
            if removed != *expected {
                self.correct_strokes += 1;
                self.total_strokes += 1;
            }
        }
    }

    fn pop_one(&mut self) {
        if let Some(removed) = self.input.pop() {
            let index = self.input.len();
            self.note_removed(index, removed);
        }
    }

    pub fn backspace(&mut self) {
        self.pop_one();
    }

    pub fn delete_word(&mut self) {
        while matches!(self.input.last(), Some(' ')) {
            self.pop_one();
        }
        while !self.input.is_empty() && !matches!(self.input.last(), Some(' ')) {
            self.pop_one();
        }
    }

    fn push_char(&mut self, c: char, count_strokes: bool) {
        if self.input.len() >= self.target.len() {
            return;
        }
        if self.input.is_empty() {
            self.started = Some(Instant::now());
        }
        if count_strokes {
            self.total_strokes += 1;
            if let Some(expected) = self.target.get(self.input.len()) {
                if c == *expected {
                    self.correct_strokes += 1;
                }
            }
        }
        self.input.push(c);
        self.finish_lesson_if_complete();
    }

    pub fn type_char(&mut self, raw: char) {
        let translated = translate(raw, self.emu_in, self.emu_out);
        if translated.is_alphabetic() || translated == ' ' {
            self.push_char(translated, true);
        }
    }

    pub fn enter(&mut self) {
        self.push_char(' ', false);
    }
}
RS
"}

