        if let Some(removed) = self.input.pop() {
            let index = self.input.len();
            self.note_removed(index, removed);
        }
    }

    pub fn backspace(&mut self) {
        self.pop_one();
    }

    pub fn delete_word(&mut self) {
        while matches!(self.input.last(), Some(' ')) {
            self.pop_one();
        }
        while !self.input.is_empty() && !matches!(self.input.last(), Some(' ')) {
            self.pop_one();
        }
    }

    fn push_char(&mut self, c: char, count_strokes: bool) {
        if self.input.len() >= self.target.len() {
            return;
