{"command":"cat > /workspace/src/ui.rs <<'RS'
use crate::game::Game;
use crate::layouts::keyboard_lines;
use ratatui::{
    buffer::Buffer,
    layout::Rect,
    style::{Color, Modifier, Style},
    Frame,
};
use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

const BOX_WIDTH: u16 = 79;

fn display_width(text: &str) -> usize {
    UnicodeWidthStr::width(text)
}

fn draw_string(buffer: &mut Buffer, x: u16, y: u16, text: &str, max_x: u16, style: Style) {
    if x >= max_x || y >= buffer.area().height {
        return;
    }
    let max_width = max_x.saturating_sub(x) as usize;
    if max_width == 0 {
        return;
    }
    buffer.set_stringn(x, y, text, max_width, style);
}

fn draw_repeated(buffer: &mut Buffer, x: u16, y: u16, symbol: &str, count: u16, max_x: u16, style: Style) {
    for offset in 0..count {
        let current_x = x.saturating_add(offset);
        if current_x >= max_x {
            break;
        }
        if let Some(cell) = buffer.cell_mut((current_x, y)) {
            cell.set_symbol(symbol);
            cell.set_style(style);
        }
    }
}

fn centered_x(width: usize) -> u16 {
    if width > 77 {
        1
    } else {
        39u16.saturating_sub((width / 2) as u16)
    }
}

pub fn render(frame: &mut Frame, game: &Game) {
    let area = frame.area();
    let required_height = if game.show_keyboard { 20 } else { 13 };
    if area.width < BOX_WIDTH || area.height < required_height {
        render_warning(frame, game);
        return;
    }

    let height: u16 = if game.show_keyboard { 19 } else { 13 };
    let buffer = frame.buffer_mut();
    let default = Style::default();
    let grey = Style::default().fg(Color::Gray);
    let bold = Style::default().add_modifier(Modifier::BOLD);

    // Outer rounded border.
    if let Some(cell) = buffer.cell_mut((0, 0)) {
        cell.set_symbol("╭");
        cell.set_style(default);
    }
    draw_repeated(buffer, 1, 0, "─", 77, BOX_WIDTH, default);
    if let Some(cell) = buffer.cell_mut((78, 0)) {
        cell.set_symbol("╮");
        cell.set_style(default);
    }
    for y in 1..height.saturating_sub(1) {
        if let Some(cell) = buffer.cell_mut((0, y)) {
            cell.set_symbol("│");
            cell.set_style(default);
        }
        if let Some(cell) = buffer.cell_mut((78, y)) {
            cell.set_symbol("│");
            cell.set_style(default);
        }
    }
    let bottom = height - 1;
    if let Some(cell) = buffer.cell_mut((0, bottom)) {
        cell.set_symbol("╰");
        cell.set_style(default);
    }
    draw_repeated(buffer, 1, bottom, "─", 77, BOX_WIDTH, default);
    if let Some(cell) = buffer.cell_mut((78, bottom)) {
        cell.set_symbol("╯");
        cell.set_style(default);
    }

    // Title in the top border.
    draw_string(buffer, 66, 0, " Quit ", 78, default);
    draw_string(
        buffer,
        72,
        0,
        "<esc> ",
        78,
        Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD),
    );

    // Separators.
    for y in [2, 4, height - 4] {
        draw_repeated(buffer, 1, y, "─", 77, 78, default);
    }

    // Header.
    draw_string(buffer, 20, 1, "               ngrrram!", 78, bold);
    draw_string(
        buffer,
        43,
        1,
        "   by winterveil",
        78,
        Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC),
    );

    // Lesson information.
    let lesson_label = format!("    Lesson #{}", game.lesson_number);
    draw_string(buffer, 1, 3, &lesson_label, 78, default);
    let green_text = format!("✔: {}, ", game.successes);
    let green_width = display_width(&green_text);
    let green_x = 70usize.saturating_sub(green_width) as u16;
    draw_string(
        buffer,
        green_x,
        3,
        &green_text,
        78,
        Style::default().fg(Color::Green),
    );
    let red_text = format!("✘: {}    ", game.failures);
    draw_string(buffer, 70, 3, &red_text, 78, Style::default().fg(Color::Red));

    // Target and typed-underneath lines.
    let target_text: String = game.target.iter().collect();
    let target_width = display_width(&target_text);
    let target_x = centered_x(target_width);
    let mut x = target_x;
    for (index, expected) in game.target.iter().enumerate() {
        let typed = game.input.get(index);
        let shown = if *expected == ' ' && typed.is_some() && typed != Some(expected) {
            '•'
        } else {
            *expected
        };
        let mut style = bold;
        if let Some(actual) = typed {
            style = if actual == expected {
                Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
            };
        }
        let symbol = shown.to_string();
        draw_string(buffer, x, 6, &symbol, 78, style);
        x = x.saturating_add(UnicodeWidthChar::width(shown).unwrap_or(0) as u16);
        if x >= 78 {
            break;
        }
    }

    let mut underneath = String::new();
    for (index, expected) in game.target.iter().enumerate() {
        if let Some(actual) = game.input.get(index) {
            if actual != expected {
                underneath.push(*actual);
            } else {
                underneath.push(' ');
            }
        } else {
            underneath.push(' ');
        }
    }
    let underneath_width = display_width(&underneath);
    let underneath_x = centered_x(underneath_width);
    draw_string(
        buffer,
        underneath_x,
        7,
        &underneath,
        78,
        Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC),
    );

    // Keyboard.
    if game.show_keyboard {
        let kb_x: u16 = if game.cat { 6 } else { 14 };
        let kb_width = 78u16.saturating_sub(kb_x);
        buffer.set_style(Rect::new(kb_x, 8, kb_width, 7), grey);
        for (index, line) in keyboard_lines(game.emu_out, game.show_ortho).iter().enumerate() {
            draw_string(buffer, kb_x, 8 + index as u16, line, 78, grey);
        }
    }

    // Lesson statistics.
    draw_stats(buffer, game, height - 3, true);
    draw_stats(buffer, game, height - 2, false);

    // Cat companion. It is drawn last, clipped to the main box.
    // (in function below, after buffer borrow code continues)
    if game.cat {
        buffer.set_style(Rect::new(61, 10, 17, 8), default);
        let cat_lines = [
            "    /\\_/\\",
            "   >(•༝• )<",
            "    |    \\",
            "    || |  )",
            "    ll-l-//",
            "/▔▔▔▔▔▔▔▔||▔▔\\",
            "          \\\\",
            "            >",
        ];
        for (index, line) in cat_lines.iter().enumerate() {
            let y = 10 + index as u16;
            if y >= height {
                break;
            }
            draw_string(buffer, 61, y, line, 78, default);
        }
    }

    // The typing cursor follows the target text.
    let cursor_x = 39u16
        .wrapping_sub((game.target.len() / 2) as u16)
        .wrapping_add(game.input.len() as u16);
    frame.set_cursor_position((cursor_x, 6));
}

fn draw_stats(buffer: &mut Buffer, game: &Game, y: u16, wpm: bool) {
    let grey = Style::default().fg(Color::Gray);
    let default = Style::default();
    let mut x = 1u16;
    let spans: Vec<(String, Style)> = if wpm {
        vec![
            (format!("  need >= {:>3}WPM,   avg. ", game.wpm_needed), grey),
            (format!("{:>3}WPM", game.avg_wpm), default),
            (",   last".to_string(), grey),
            (format!(" {:>3}WPM", game.last_wpm), default),
        ]
    } else {
        vec![
            (format!("  need >= {:>3}% Acc, avg. ", game.acc_needed), grey),
            (format!("{:>3}% Acc", game.avg_acc), default),
            (", last".to_string(), grey),
            (format!(" {:>3}% Acc", game.last_acc), default),
        ]
    };
    for (text, style) in spans {
        let width = display_width(&text) as u16;
        draw_string(buffer, x, y, &text, 78, style);
        x = x.saturating_add(width);
        if x >= 78 {
            break;
        }
    }
}

fn render_warning(frame: &mut Frame, game: &Game) {
    let area = frame.area();
    let lines: Vec<&str> = if game.show_keyboard {
        vec![
            "Please resize your terminal to at least 80x20,",
            "or consider disabling the keyboard display with --nokb",
            "",
            "<esc> or <ctrl-c> to quit",
        ]
    } else {
        vec![
            "Please resize your terminal to at least 80x13.",
            "<esc> or <ctrl-c> to quit",
        ]
    };
    let buffer = frame.buffer_mut();
    for (index, line) in lines.iter().enumerate() {
        if line.is_empty() {
            continue;
        }
        let y = index as u16;
        if y >= area.height {
            break;
        }
        let width = display_width(line);
        let x = (area.width / 2).saturating_sub((width / 2) as u16);
        draw_string(buffer, x, y, line, area.width, Style::default());
    }
}
RS
