{"command":"cat > /workspace/src/main.rs <<'RS'
mod data;
mod game;
mod layouts;
mod ngrams;
mod ui;

use clap::{Arg, ArgAction, Command};
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use game::Game;
use std::{error::Error, io, process, time::Duration};

fn cli() -> Command {
    Command::new("ngrrram")
        .arg(
            Arg::new("n")
                .short('n')
                .long("n")
                .value_name("2|3|4|w|file")
                .default_value("2")
                .help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."),
        )
        .arg(
            Arg::new("top")
                .short('t')
                .long("top")
                .value_name("1-200")
                .default_value("50")
                .value_parser(clap::value_parser!(i32))
                .help("use the top X ngrams ordered by usage."),
        )
        .arg(
            Arg::new("combi")
                .short('c')
                .long("combi")
                .value_name("1-200")
                .default_value("2")
                .value_parser(clap::value_parser!(i32))
                .help("how many different ngrams to use in a single lesson."),
        )
        .arg(
            Arg::new("rep")
                .short('r')
                .long("rep")
                .value_name("number")
                .default_value("3")
                .value_parser(clap::value_parser!(i32))
                .help("how often to repeat *each* different ngram in a lesson."),
        )
        .arg(
            Arg::new("wpm")
                .short('w')
                .long("wpm")
                .value_name("number")
                .default_value("40")
                .value_parser(clap::value_parser!(i32))
                .help("the wpm threshold at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("acc")
                .short('a')
                .long("acc")
                .value_name("0-100")
                .default_value("94")
                .value_parser(clap::value_parser!(i32))
                .help("the accuracy in percent at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("emu-in")
                .long("emu-in")
                .value_name("layout")
                .default_value("")
                .help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("emu-out")
                .long("emu-out")
                .value_name("layout")
                .default_value("")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("show-ortho")
                .long("show-ortho")
                .action(ArgAction::SetTrue)
                .help("show keyboard in ortholinear format"),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
}

fn invalid(name: &str, range: &str) -> ! {
    println!("Invalid argument for {}. Use a number between {}.", name, range);
    process::exit(1);
}

fn main() -> Result<(), Box<dyn Error>> {
    let matches = cli().get_matches();
    let n = matches.get_one::<String>("n").unwrap().clone();
    let top = *matches.get_one::<i32>("top").unwrap();
    let combi = *matches.get_one::<i32>("combi").unwrap();
    let rep = *matches.get_one::<i32>("rep").unwrap();
    let wpm = *matches.get_one::<i32>("wpm").unwrap();
    let acc = *matches.get_one::<i32>("acc").unwrap();
    let emu_in = matches.get_one::<String>("emu-in").unwrap().clone();
    let emu_out = matches.get_one::<String>("emu-out").unwrap().clone();
    let show_ortho = matches.get_flag("show-ortho");
    let nokb = matches.get_flag("nokb");
    let cat = matches.get_flag("cat");

    if !(1..=200).contains(&top) {
        invalid("top", "1 and 200");
    }
    if !(1..=200).contains(&combi) {
        invalid("combi", "1 and 200");
    }
    if !(1..=200).contains(&rep) {
        invalid("rep", "1 and 200");
    }
    if !(1..=200).contains(&wpm) {
        invalid("wpm", "1 and 200");
    }
    if !(0..=100).contains(&acc) {
        invalid("acc", "0 and 100");
    }
    if emu_in.is_empty() != emu_out.is_empty() {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }

    let pool = ngrams::load_pool(&n);
    let mut game = Game::new(
        pool, top, combi, rep, wpm, acc, &emu_in, &emu_out, show_ortho, !nokb, cat,
    );

    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    loop {
        terminal.draw(|frame| ui::render(frame, &game))?;
        if game.target.is_empty() {
            game.new_lesson();
            continue;
        }
        if event::poll(Duration::from_millis(16))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        game.delete_word();
                    }
                    KeyCode::Backspace if key.modifiers == KeyModifiers::ALT => {
                        game.delete_word();
                    }
                    KeyCode::Backspace => game.backspace(),
                    KeyCode::Enter => game.enter(),
                    KeyCode::Char(c) => game.type_char(c),
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(io::stdout(), LeaveAlternateScreen)?;
    Ok(())
}
RS
