            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
}

fn invalid(name: &str, range: &str) -> ! {
    println!("Invalid argument for {}. Use a number between {}.", name, range);
    process::exit(1);
}

fn main() -> Result<(), Box<dyn Error>> {
    let matches = cli().get_matches();
    let n = matches.get_one::<String>("n").unwrap().clone();
    let top = *matches.get_one::<i32>("top").unwrap();
    let combi = *matches.get_one::<i32>("combi").unwrap();
    let rep = *matches.get_one::<i32>("rep").unwrap();
    let wpm = *matches.get_one::<i32>("wpm").unwrap();
    let acc = *matches.get_one::<i32>("acc").unwrap();
    let emu_in = matches.get_one::<String>("emu-in").unwrap().clone();
    let emu_out = matches.get_one::<String>("emu-out").unwrap().clone();
    let show_ortho = matches.get_flag("show-ortho");
    let nokb = matches.get_flag("nokb");
    let cat = matches.get_flag("cat");

    if !(1..=200).contains(&top) {
        invalid("top", "1 and 200");
    }
    if !(1..=200).contains(&combi) {
        invalid("combi", "1 and 200");
    }
    if !(1..=200).contains(&rep) {
        invalid("rep", "1 and 200");
    }
    if !(1..=200).contains(&wpm) {
        invalid("wpm", "1 and 200");
    }
    if !(0..=100).contains(&acc) {
        invalid("acc", "0 and 100");
    }
    if emu_in.is_empty() != emu_out.is_empty() {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }

    let pool = ngrams::load_pool(&n);
    let mut game = Game::new(
        pool, top, combi, rep, wpm, acc, &emu_in, &emu_out, show_ortho, !nokb, cat,
    );

    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    loop {
        terminal.draw(|frame| ui::render(frame, &game))?;
        if game.target.is_empty() {
            game.new_lesson();
            continue;
        }
        if event::poll(Duration::from_millis(16))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        game.delete_word();
                    }
                    KeyCode::Backspace if key.modifiers == KeyModifiers::ALT => {
                        game.delete_word();
                    }
                    KeyCode::Backspace => game.backspace(),
                    KeyCode::Enter => game.enter(),
                    KeyCode::Char(c) => game.type_char(c),
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(io::stdout(), LeaveAlternateScreen)?;
    Ok(())
}
