            if error.kind() == ErrorKind::DisplayHelp {
                text = text.replace("[default: \\"\\"]", "[default: ]");
            }
            if error.kind() == ErrorKind::UnknownArgument
                && text.contains("a similar argument exists:")
                && !text.contains("'--help'")
            {
                let mut lines: Vec<String> = text.lines().map(|line| line.to_string()).collect();
                for line in &mut lines {
                    if let Some(rest) = line.strip_prefix("Usage: ") {
                        let bin = rest.split_whitespace().next().unwrap_or("executable");
                        *line = format!(
                            "Usage: {} <--n <2|3|4|w|file>|--top <1-200>|--combi <1-200>|--rep <number>|--wpm <number>|--acc <0-100>|--emu-in <layout>|--emu-out <layout>|--show-ortho|--nokb|--cat>",
                            bin
                        );
                    }
                }
                text = lines.join("\\n");
                if error.render().to_string().ends_with('\\n') {
                    text.push('\\n');
                }
            }
            if use_stderr {
                eprint!("{}", text);
            } else {
                print!("{}", text);
            }
            process::exit(code);
        }
    }
