import os, sys, time, shlex, re
sys.path.insert(0,'/tmp')
import importlib
import probe_new
def sequence(BIN, args, steps, name):
    os.environ["PROBE_BIN"]=BIN; importlib.reload(probe_new)
    s=probe_new.Sess(name,args,80,24)
    snaps=[]
    snaps.append((s.cap(),s.cap(True)))
    for step in steps:
        kind=step[0]
        if kind=="l": # literal string
            probe_new.run(f"tmux send-keys -t {name} -l {shlex.quote(step[1])}")
        elif kind=="key":
            probe_new.run(f"tmux send-keys -t {name} {step[1]}")
        elif kind=="hex":
            bs=" ".join(step[1][i:i+2] for i in range(0,len(step[1]),2))
            probe_new.run(f"tmux send-keys -t {name} -H {bs}")
        elif kind=="sleep": time.sleep(step[1])
        time.sleep(step[2] if len(step)>2 else 0.35)
        snaps.append((s.cap(),s.cap(True)))
    s.kill(); return snaps

def normalize(text):
    # mask WPM numbers (avg/last values) while keeping format roughly: replace digit runs in need lines with '#'*len
    out=[]
