    match cli().try_get_matches() {
        Ok(matches) => matches,
        Err(error) => {
            let code = error.exit_code();
            let use_stderr = error.use_stderr();
            let plain = error.render().to_string();
            let mut text = format!("{}", error.render().ansi());
            if error.kind() == ErrorKind::DisplayHelp {
                text = text.replace("[default: \\"\\"]", "[default: ]");
            }
            if error.kind() == ErrorKind::UnknownArgument
                && plain.contains("a similar argument exists:")
                && !plain.contains("a similar argument exists: '--help'")
            {
                let plain_lines: Vec<&str> = plain.lines().collect();
                let mut raw_lines: Vec<String> = text.lines().map(|line| line.to_string()).collect();
                for (index, raw_line) in raw_lines.iter_mut().enumerate() {
                    if let Some(plain_line) = plain_lines.get(index) {
                        if let Some(rest) = plain_line.strip_prefix("Usage: ") {
                            let bin = rest.split_whitespace().next().unwrap_or("executable");
                            if let Some(bin_start) = raw_line.find(bin) {
                                let mut cut = bin_start + bin.len();
