                                    prefix
                                );
                            }
                        }
                    }
                }
                text = raw_lines.join("\\n");
                if plain.ends_with('\\n') {
                    text.push('\\n');
                }
            }
            if use_stderr {
                anstream::eprint!("{}", text);
                let _ = std::io::Write::flush(&mut std::io::stderr());
            } else {
                anstream::print!("{}", text);
                let _ = std::io::Write::flush(&mut std::io::stdout());
            }
            process::exit(code);
        }
    }
}

