def seq(BIN,args,steps,name):
    os.environ["PROBE_BIN"]=BIN; importlib.reload(probe_new)
    s=probe_new.Sess(name,args,80,24); out=[s.cap()]
    for step in steps:
        if step[0]=="l": probe_new.run(f"tmux send-keys -t {name} -l {shlex.quote(step[1])}")
        elif step[0]=="key": probe_new.run(f"tmux send-keys -t {name} {step[1]}")
        elif step[0]=="hex": probe_new.run(f"tmux send-keys -t {name} -H {' '.join(step[1][i:i+2] for i in range(0,len(step[1]),2))}")
        time.sleep(0.3); out.append(re.sub(r'\d+WPM','#WPM',s.cap()))
    s.kill(); return out
cases=[
 ("--nokb -n /tmp/testfiles/words.txt -t 1 -c 2 -r 2 -w 1 -a 0", [("l","alpha alpha alpha alpha"),("key","BSpace"),("l"," ")]),
 ("--nokb -n /tmp/testfiles/spaces.txt -t 2 -c 2 -r 1 -w 1 -a 0", [("l","alpha"),("key","BSpace")]),
]
for idx,(args,steps) in enumerate(cases):
    a=seq("/workspace/executable",args,steps,"fa"); b=seq("/tmp/executable",args,steps,"fb")
    print(idx,"MATCH" if a==b else "DIFF")
    if a!=b:
        for i,(x,y) in enumerate(zip(a,b)):
